def _hashable(key):
    """Best-effort conversion of a key to something hashable.

    Returns (ok, normalized_key). Tries `hash(key)` first; if that fails
    with TypeError (unhashable key), walks the value and recursively
    normalizes unhashable containers (dicts, lists, sets) into hashable
    equivalents. On any other failure, returns (False, key) so the caller
    falls back to a linear scan of the original keys.
    """
    try:
        hash(key)
        return True, key
    except TypeError:
        pass
    try:
        return True, _normalize(key)
    except Exception:
        return False, key


def _normalize(v):
    if isinstance(v, dict):
        return ("__dict__", tuple(sorted(((k, _normalize(x)) for k, x in v.items()),
                                         key=lambda p: repr(p[0]))))
    if isinstance(v, (list, tuple, set, frozenset)):
        return tuple(_normalize(x) for x in v)
    return v


def dedupe(records, key=None):
    seen = set()
    seen_list = []  # original keys for the fallback equality scan
    out = []
    for r in records:
        k = key(r) if key else r
        ok, nk = _hashable(k)
        if ok:
            if nk in seen:
                continue
            seen.add(nk)
        else:
            if any(k == s for s in seen_list):
                continue
            seen_list.append(k)
        out.append(r)
    return out
