def _hashable(key):
    """Return (ok, normalized_key) for use in a set.

    If the key is already hashable it is used as-is.  Unhashable keys
    (dicts, lists, ...) are recursively rewritten into hashable
    equivalents (dicts become canonicalized tuples, lists become tuples,
    sets become frozensets), which is cheap and preserves equality for
    the common JSON-like shapes.  If normalization fails the key is left
    alone and (False, key) is returned so the caller can fall back to a
    linear scan.
    """
    try:
        hash(key)
        return True, key
    except TypeError:
        pass
    try:
        return True, _normalize(key)
    except Exception:
        return False, key


def _normalize(v):
    if type(v) is dict:
        return tuple(
            sorted(
                ((k, _normalize(x)) for k, x in v.items()),
                key=lambda p: (type(p[0]), p[0]),
            )
        )
    if type(v) is list:
        return tuple(_normalize(x) for x in v)
    if type(v) is set:
        return frozenset(_normalize(x) for x in v)
    return v


def dedupe(records, key=None):
    seen = set()
    seen_list = []  # original keys, only for un-normalizable fallback
    out = []
    for r in records:
        k = key(r) if key else r
        ok, nk = _hashable(k)
        if ok:
            if nk in seen:
                continue
            seen.add(nk)
        else:
            if any(k == s for s in seen_list):
                continue
            seen_list.append(k)
        out.append(r)
    return out
