{"content":""""Remove duplicate records, keeping the first occurrence.

Two keys are considered duplicates exactly when they are equal (``==``),
including nested structures.  Unhashable keys (dicts, lists, sets) are
recursively rewritten into hashable twins (dicts -> canonicalized tuples,
lists -> tuples, sets -> frozensets) and those twins are compared in a
set, which gives the same ``==`` result for JSON-like data.  The only
edge case where the twins diverge from raw ``==`` (e.g. a container
holding both ``0`` and ``0.0``) is handled by falling back to a linear
scan of the original keys, so the semantics never change.
"""

import collections


def _hashable(key):
    """Return (ok, key_for_set).  See module docstring."""
    try:
        hash(key)
        return True, key
    except TypeError:
        pass
    try:
        nk = _normalize(key)
    except Exception:
        return False, key
    # Confirm the normalized form really is hashable.
    try:
        hash(nk)
    except TypeError:
        return False, key
    return True, nk


def _normalize(v):
    if type(v) is dict:
        items = tuple(
            sorted(
                ((_normalize(k), _normalize(x)) for k, x in v.items()),
                key=lambda p: (type(p[0]), p[0]),
            )
        )
        return _DictKey(items)
    if type(v) is list:
        return tuple(_normalize(x) for x in v)
    if type(v) is set:
        return _FrobKey(frozenset(_normalize(x) for x in v))
    return v


class _DictKey(tuple):
    """Hashable stand-in for a dict; order-insensitive and key-type-sensitive."""

    __slots__ = ()

    def __eq__(self, other):
        return type(other) is _DictKey and tuple(self) == tuple(other)

    def __hash__(self):
        h = 0
        for item in self:
            h ^= hash(item)
        return h


class _FrobKey(tuple):
    """Hashable stand-in for a set; order-insensitive, distinct from frozenset."""

    __slots__ = ()

    def __new__(cls, fs):
        return tuple.__new__(cls, fs)

    def __eq__(self, other):
        return type(other) is _FrobKey and frozenset(self) == frozenset(other)

    def __hash__(self):
        return hash(frozenset(self))


def dedupe(records, key=None):
    seen = set()
    seen_list = []  # original keys, only for un-normalizable fallback
    out = []
    for r in records:
        k = key(r) if key else r
        ok, nk = _hashable(k)
        if ok:
            if nk in seen:
                continue
            seen.add(nk)
        else:
            if any(k == s for s in seen_list):
                continue
            seen_list.append(k)
        out.append(r)
    return out
